def solve_n_queens_brute(n):
    def is_valid(cols):
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                if cols[i] == cols[j] or abs(cols[i] - cols[j]) == j - i:  # check all pairs
                    return False
        return True

    def generate(cols):
        if len(cols) == n:
            if is_valid(cols):
                yield cols[:]
            return
        for c in range(n):
            cols.append(c)
            yield from generate(cols)
            cols.pop()

    result = []
    for cols in generate([]):
        board = ['.' * c + 'Q' + '.' * (n - c - 1) for c in cols]
        result.append(board)
    return result

