#include <bits/stdc++.h>
using namespace std;

vector<vector<string>> result;
set<int> cols, diag1, diag2;
vector<string> board;

void backtrack(int row, int n) {
    if (row == n) { result.push_back(board); return; }
    for (int col = 0; col < n; col++) {
        if (cols.count(col) || diag1.count(row - col) || diag2.count(row + col)) continue;  // pruned
        cols.insert(col); diag1.insert(row - col); diag2.insert(row + col);
        board[row][col] = 'Q';
        backtrack(row + 1, n);
        board[row][col] = '.';
        cols.erase(col); diag1.erase(row - col); diag2.erase(row + col);   // undo
    }
}

vector<vector<string>> solveNQueens(int n) {
    board.assign(n, string(n, '.'));
    backtrack(0, n);
    return result;
}
